<script setup lang="ts">
import { ref, watch } from 'vue';
import { useRoute, useRouter, RouterLink } from 'vue-router';
import axios from 'axios';import ListingCarousel from './ListingCarousel.vue';
interface Product {id:number;title:string;description:string;price:number;location:string;imageUrl:string;status:string;ownerId:number|null;ownerName:string;kind:string}
const route=useRoute(),router=useRouter();
const product=ref<Product|null>(null),keyword=ref(''),loading=ref(false),error=ref('');
const contacting=ref(false),tradeError=ref('');
async function contact(){if(!product.value?.ownerId)return;contacting.value=true;tradeError.value='';try{const token=(await axios.get('/api/auth/csrf')).data.token;const {data}=await axios.post('/api/chats/with/'+product.value.ownerId,null,{headers:{'X-XSRF-TOKEN':token}});router.push('/messages/'+data.id);}catch(e){tradeError.value=axios.isAxiosError(e)&&e.response?.status===400?'这是你自己发布的信息':'无法发起私聊，请稍后重试';}finally{contacting.value=false;}}
let request=0;
async function load(){const current=++request;loading.value=true;error.value='';product.value=null;try{
 if(route.params.id){const {data}=await axios.get<Product>('/api/products/'+route.params.id);if(current===request)product.value=data;}
 else{keyword.value=String(route.query.keyword||'');}
 }catch(e){if(current===request)error.value=axios.isAxiosError(e)&&e.response?.status===404?'这件商品不存在':'暂时无法加载，请稍后重试';}finally{if(current===request)loading.value=false;}}
function search(){router.push({path:'/market',query:keyword.value?{keyword:keyword.value}:{}});}
watch(()=>route.fullPath,load,{immediate:true});
</script>
<template><section class="market"><div class="market-heading"><p>SDU / CAMPUS MARKET</p><h1>{{ route.params.id ? '好物详情' : '校园二手市场' }}</h1><span>让闲置流转，让校园生活多一份可能。</span></div>
<div class="market-body"><RouterLink v-if="route.params.id" to="/market" class="back-link">← 返回二手市场</RouterLink><form v-else class="search-form" @submit.prevent="search"><label for="search">寻找校园好物</label><div><input id="search" v-model="keyword" maxlength="100" placeholder="搜索商品名称或描述"><button>搜索</button></div></form>
<p v-if="loading" role="status">正在加载好物…</p><div v-else-if="error" role="alert"><p>{{ error }}</p><button @click="load">重新加载</button></div>
<article v-else-if="product" class="product-detail"><img :src="product.imageUrl" :alt="product.title"><div><span class="product-tag">{{product.kind==='WANTED'?'求购 / 感兴趣':'校园闲置'}} · {{ product.status==='AVAILABLE'?'在售':product.status==='RESERVED'?'已预订':product.status==='SOLD'?'已售出':'已下架' }}</span><h2>{{ product.title }}</h2><p class="price">¥ {{ Number(product.price).toFixed(2) }}</p><p class="location">交易地点：{{ product.location || '待补充' }}</p><RouterLink v-if="product.ownerId" class="owner" :to="'/people/'+product.ownerId"><img :src="'/api/conversations/avatars/'+product.ownerId" alt="发布者头像"><span>{{product.ownerName}}<small>ID {{product.ownerId}} · 查看主页</small></span></RouterLink><h3>{{product.kind==='WANTED'?'求购描述':'商品描述'}}</h3><p class="description">{{ product.description || '卖家暂未填写描述' }}</p><p class="trade-note">联系发布者沟通，双方自行约定线下交接。</p><p role="alert">{{tradeError}}</p><button :disabled="contacting||!product.ownerId" @click="contact">{{contacting?'打开私聊…':product.kind==='WANTED'?'联系求购者':'联系卖家'}}</button><p v-if="!product.ownerId">历史发布者尚未关联，暂时无法联系。</p></div></article>
<template v-if="!route.params.id"><ListingCarousel kind="SELL" :keyword="String(route.query.keyword||'')"/><ListingCarousel kind="WANTED" :keyword="String(route.query.keyword||'')"/></template></div></section></template>
<style scoped>
.market{flex:1;background:#f6f4ee;color:#293d3b}.market-heading{padding:45px 7%;background:linear-gradient(90deg,#172d3cda,#172d3c80),url('/assets/legacy/images/sdu.jpg') center 45%/cover;color:white}.market-heading>p{font-size:10px;letter-spacing:3px;color:#ecd2a9}.market-heading h1{font-size:34px;margin:14px 0;letter-spacing:2px}.market-heading>span{font-size:13px;color:#ffffffe0}.market-body{max-width:1200px;margin:auto;padding:36px 28px 60px}.search-form{display:flex;justify-content:space-between;align-items:center;gap:20px}.search-form label{font-size:20px;font-weight:600}.search-form>div{display:flex;width:min(480px,60%)}input{padding:13px;border:1px solid #d3d7cd;border-radius:4px 0 0 4px;min-width:0;flex:1;font:inherit;font-size:13px}button{background:#304b49;color:white;border:0;padding:12px 24px;border-radius:3px}button:disabled{opacity:.4;cursor:default}.product-tag{font-size:10px;color:#92724b;letter-spacing:1px}.back-link{color:#516b62;text-decoration:none;font-size:13px;display:inline-block;margin-bottom:25px}.product-detail{display:grid;grid-template-columns:1fr 1fr;gap:45px;background:white;padding:35px;border-radius:8px}.product-detail>img{width:100%;max-height:500px;object-fit:contain;background:#f1f1ec}.product-detail h2{font-size:28px;overflow-wrap:anywhere}.price{font-size:30px;color:#a44e36}.location{font-size:13px;color:#7e887f;border-bottom:1px solid #e5e7de;padding-bottom:20px}.product-detail h3{font-size:15px}.description{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.9;font-size:14px;max-height:400px;overflow:auto}.trade-note{font-size:12px;background:#f8f4e9;color:#8c7450;padding:14px;line-height:1.8}@media(max-width:850px){.product-detail{grid-template-columns:1fr;padding:20px;gap:20px}.search-form{align-items:flex-start;flex-direction:column}.search-form>div{width:100%}}@media(max-width:500px){.market-body{padding:25px 20px}}
.owner{display:flex;align-items:center;gap:12px;padding:18px;background:#faf6eb;border-radius:8px;color:#304b49;text-decoration:none}.owner img{width:45px;height:45px;border-radius:50%;object-fit:cover}.owner small{display:block;font-size:10px;color:#8a907a;margin-top:7px}</style>
